    --font-display: "Bricolage Grotesque", sans-serif;
    --font-body: "IBM Plex Sans", sans-serif;
    --font-count: "IBM Plex Mono", monospace;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--desk);
    background-image:
      repeating-linear-gradient(90deg, var(--desk-line) 0 1px, transparent 1px 96px);
    color: var(--paper);
    font-family: var(--font-body);
    -webkit-font-smoothing: antialiased;
  }

  .desk {
    max-width: 1180px;
    margin: 0 auto;
    padding: 5rem 1.5rem 4rem;
  }

